/**
 * The OpenAPI 3.1 document (SDK unit 13, issue #245, ADR-0080): route coverage in both directions,
 * validity against the OpenAPI 3.1 schema, determinism, staleness, and a client generated by an
 * off-the-shelf generator calling `GET /api/me`.
 */
import { readFile } from 'node:fs/promises';
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import path from 'node:path';

import { Validator } from '@seriousme/openapi-schema-validator';
import {
  CONTRACTS_MINIMUM_VERSION_HEADER,
  CONTRACTS_VERSION_HEADER,
} from '@indx-workspace/contracts';
import { MeResponseSchema, type MeResponse } from '@indx-workspace/contracts/team';
import { API_ROUTE_EXCLUSIONS, API_ROUTES, type ApiBody } from '@indx-workspace/contracts/routes';
import createClient from 'openapi-fetch';
import openapiTS, { astToString } from 'openapi-typescript';
import ts from 'typescript';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import {
  OPENAPI_OUTPUT,
  buildOpenApiDocument,
  renderOpenApiDocument,
} from '../../scripts/docs/generate-openapi.mjs';
import { readDeclarationFiles, requireString } from '../inventory-support.js';

const repoRoot = path.resolve(import.meta.dirname, '../..');
const HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete'] as const;

let rendered: string;
let document: Record<string, unknown>;

beforeAll(async () => {
  rendered = await renderOpenApiDocument(repoRoot);
  document = JSON.parse(rendered) as Record<string, unknown>;
});

const key = (method: string, routePath: string): string => `${method.toUpperCase()} ${routePath}`;

/** Every `METHOD /path` the route inventory declares. */
function declaredRoutes(): Set<string> {
  const declared = new Set<string>();
  for (const file of readDeclarationFiles('tests/route-declarations', 'routes')) {
    for (const entry of file.entries) {
      declared.add(
        key(
          requireString(entry, 'method', file.repoPath),
          requireString(entry, 'path', file.repoPath),
        ),
      );
    }
  }
  return declared;
}

/** Every `METHOD /path` in the emitted document, in the specification's `:id` notation. */
function documentedRoutes(doc: Record<string, unknown>): Set<string> {
  const documented = new Set<string>();
  const paths = doc['paths'] as Record<string, Record<string, unknown>>;
  for (const [openApiPath, item] of Object.entries(paths)) {
    for (const method of HTTP_METHODS) {
      if (method in item) documented.add(key(method, openApiPath.replace(/\{([^}]+)\}/gu, ':$1')));
    }
  }
  return documented;
}

/** The two reasons a declared route may stay out of the document (ADR-0080). */
const BROWSER_JOURNEY = /\(04 §1\)$/u;
const PRIVATE_RUNNER_ROUTE = 'private runner route (per-run token)';
/** The Vercel Cron retention job: called by the platform, never by an SDK client (ADR-0120 clause 7). */
const PLATFORM_CRON_JOB = 'platform cron job (CRON_SECRET bearer)';
/** The web server's readiness probe: called by the platform's kubelet, never by an SDK client (#1562). */
const PLATFORM_READINESS_PROBE = 'platform readiness probe (no credential)';
/** The Builder's `aw-control` MCP door: called by the gateway with a run token, never by an SDK client (#1846). */
const RUN_CALLER_ROUTE = 'run-caller route (per-run token, aw-control tools)';

/** The OAuth 2.1 server's protocol endpoints (ADR-0134 part 3): specified by an RFC, not by this API. */
const OAUTH_PROTOCOL_ROUTE = /\(RFC \d+\)/u;

describe('route coverage', () => {
  it('excludes only browser journeys, private runner routes, OAuth protocol endpoints, the platform cron job, the readiness probe and the run-caller route', () => {
    const reasons = API_ROUTE_EXCLUSIONS.filter(
      (route) =>
        !BROWSER_JOURNEY.test(route.because) &&
        !OAUTH_PROTOCOL_ROUTE.test(route.because) &&
        route.because !== PRIVATE_RUNNER_ROUTE &&
        route.because !== PLATFORM_CRON_JOB &&
        route.because !== PLATFORM_READINESS_PROBE &&
        route.because !== RUN_CALLER_ROUTE,
    );
    const oauthOnly = API_ROUTE_EXCLUSIONS.filter((route) =>
      OAUTH_PROTOCOL_ROUTE.test(route.because),
    ).map((route) => key(route.method, route.path));
    expect(oauthOnly.sort()).toEqual(
      [
        'GET /.well-known/oauth-authorization-server',
        'GET /.well-known/oauth-protected-resource/mcp/projects/:name',
        'GET /.well-known/oauth-protected-resource/mcp/builder',
        'GET /.well-known/oauth-protected-resource/api/a2a/agents/:agentName',
        'POST /oauth/token',
        'POST /oauth/revoke',
      ].sort(),
    );
    const cronOnly = API_ROUTE_EXCLUSIONS.filter(
      (route) => route.because === PLATFORM_CRON_JOB,
    ).map((route) => key(route.method, route.path));
    expect(cronOnly).toEqual([
      'GET /api/cron/retention',
      'GET /api/cron/triggers',
      'GET /api/cron/storage-cleanup',
    ]);
    const probeOnly = API_ROUTE_EXCLUSIONS.filter(
      (route) => route.because === PLATFORM_READINESS_PROBE,
    ).map((route) => key(route.method, route.path));
    expect(probeOnly).toEqual(['GET /api/readyz']);
    const runCallerOnly = API_ROUTE_EXCLUSIONS.filter(
      (route) => route.because === RUN_CALLER_ROUTE,
    ).map((route) => key(route.method, route.path));
    expect(runCallerOnly).toEqual(['POST /api/builder/mcp']);
    expect(reasons, 'an exclusion that is neither kind').toEqual([]);
    const runnerOnly = API_ROUTE_EXCLUSIONS.filter(
      (route) => route.because === PRIVATE_RUNNER_ROUTE,
    ).map((route) => key(route.method, route.path));
    // The ENG-06 state routes, the transcript writes and the run's file search: the running agent
    // (through `apps/runner`) is their only client.
    expect(runnerOnly.sort()).toEqual(
      [
        'GET /api/sessions/:engineSessionId/file-search',
        'POST /api/sessions/:engineSessionId/transcript',
        'DELETE /api/sessions/:engineSessionId/transcript',
        ...['GET', 'POST', 'PUT', 'DELETE'].map((method) =>
          key(method, '/api/sessions/:engineSessionId/state-entries'),
        ),
        'GET /api/sessions/:engineSessionId/state-streams',
        'GET /api/sessions/:engineSessionId/state-blobs',
        'PUT /api/sessions/:engineSessionId/state-blobs',
      ].sort(),
    );
  });

  it('catalogues every declared route that is not an exclusion, and nothing else', () => {
    const declared = declaredRoutes();
    const excluded = new Set(API_ROUTE_EXCLUSIONS.map((route) => key(route.method, route.path)));
    const catalogued = new Set(API_ROUTES.map((route) => key(route.method, route.path)));

    const staleExclusions = [...excluded].filter((route) => !declared.has(route));
    expect(staleExclusions, 'an exclusion names a route nobody declares').toEqual([]);
    const withoutContract = [...declared].filter(
      (route) => !excluded.has(route) && !catalogued.has(route),
    );
    expect(
      withoutContract,
      'declared routes with no entry in packages/contracts/src/routes.ts',
    ).toEqual([]);
    const undeclared = [...catalogued].filter(
      (route) => !declared.has(route) || excluded.has(route),
    );
    expect(undeclared, 'catalogued routes the inventory does not declare as public').toEqual([]);
    expect(catalogued.size).toBe(API_ROUTES.length);
  });

  it('emits one operation per catalogued route, and no other', () => {
    const catalogued = new Set(API_ROUTES.map((route) => key(route.method, route.path)));
    expect(documentedRoutes(document)).toEqual(catalogued);
  });
});

describe('the emitted document', () => {
  it('validates against the OpenAPI 3.1 schema', async () => {
    const validator = new Validator();
    const result = await validator.validate(document);
    expect(result.errors ?? []).toEqual([]);
    expect(result.valid).toBe(true);
    expect(validator.version).toBe('3.1');
  });

  it('is deterministic: two runs, one output', async () => {
    expect(await renderOpenApiDocument(repoRoot)).toBe(rendered);
    expect(rendered.endsWith('}\n')).toBe(true);
    expect(rendered.includes('\r')).toBe(false);
  });

  it('is committed as generated', async () => {
    const committed = await readFile(path.join(repoRoot, ...OPENAPI_OUTPUT.split('/')), 'utf8');
    expect(committed, 'run `pnpm docs:generate`').toBe(rendered);
  });

  it('describes the error envelope, the contracts-version headers and the event stream', async () => {
    const built = await buildOpenApiDocument(repoRoot);
    const components = built['components'] as Record<string, Record<string, unknown>>;
    expect(Object.keys(components['responses'] ?? {})).toEqual([
      'BadRequest',
      'ContractsVersionUnsupported',
      'Problem',
    ]);
    expect(JSON.stringify(components['parameters'])).toContain(CONTRACTS_VERSION_HEADER);
    const unsupported = components['responses']?.['ContractsVersionUnsupported'] as Record<
      string,
      Record<string, unknown>
    >;
    expect(Object.keys(unsupported['headers'] ?? {}).sort()).toEqual(
      ['Upgrade', CONTRACTS_VERSION_HEADER, CONTRACTS_MINIMUM_VERSION_HEADER].sort(),
    );
    const problem = components['schemas']?.['ApiProblem'] as Record<string, unknown>;
    expect(JSON.stringify(problem)).toContain('"code"');
    const paths = built['paths'] as Record<string, Record<string, Record<string, unknown>>>;
    const events = paths['/api/runs/{id}/events']?.['get']?.['responses'] as Record<
      string,
      Record<string, Record<string, unknown>>
    >;
    expect(Object.keys(events['200']?.['content'] ?? {})).toEqual(['text/event-stream']);
  });
});

/** The quoted `METHOD /path` entries of one `new Set([...])` in the authorisation matrix. */
async function matrixRouteSet(name: string): Promise<Set<string>> {
  const source = await readFile(
    path.join(repoRoot, 'apps/web/server/rbac/authorisation-matrix.test.ts'),
    'utf8',
  );
  const match = new RegExp(`const ${name} = new Set\\(\\[([^\\]]*)\\]\\)`, 'u').exec(source);
  if (match?.[1] === undefined) throw new Error(`${name} not found in the authorisation matrix`);
  return new Set([...match[1].matchAll(/'([^']+)'/gu)].map((entry) => entry[1] ?? ''));
}

describe('per-route credentials', () => {
  it('marks exactly the public and identity-only routes of the authorisation matrix', async () => {
    const identityOnly = await matrixRouteSet('IDENTITY_ONLY_ROUTES');
    const exempt = new Set([...(await matrixRouteSet('PUBLIC_ROUTES')), ...identityOnly]);
    expect(identityOnly.size).toBeGreaterThan(0);
    const catalogued = API_ROUTES.map((route) => key(route.method, route.path));
    const expected = catalogued.filter((route) => exempt.has(route)).sort();
    const marked = API_ROUTES.filter((route) => route.security !== undefined)
      .map((route) => key(route.method, route.path))
      .sort();
    expect(marked).toEqual(expected);
    // Every identity-only route proves its caller by a credential of its own: the invitation
    // cookie for `/accept`, or (ADR-0083) the user token for the two routes that act on it, or
    // (ADR-0135) the endpoint credential of a published agent's A2A routes.
    const identityProofs = API_ROUTES.filter(
      (route) =>
        route.security === 'invitation-identity' ||
        route.security === 'user-token' ||
        route.security === 'endpoint-credential',
    ).map((route) => key(route.method, route.path));
    expect(identityProofs).toEqual(catalogued.filter((route) => identityOnly.has(route)));
    const invitationIdentity = API_ROUTES.filter(
      (route) => route.security === 'invitation-identity',
    ).map((route) => key(route.method, route.path));
    expect(invitationIdentity).toEqual(['POST /api/invitations/:id/accept']);
  });

  it('emits the route security in place of the global one', () => {
    const paths = document['paths'] as Record<string, Record<string, Record<string, unknown>>>;
    expect(paths['/api/setup/runtime-detect']?.['get']?.['security']).toEqual([]);
    expect(paths['/api/invitations/{id}/accept']?.['post']?.['security']).toEqual([
      { invitationCookie: [] },
    ]);
    expect(paths['/api/me']?.['get']?.['security']).toBeUndefined();
  });
});

/**
 * The bodies the contracts do not describe yet, frozen: the live set may only shrink. A new route
 * brings its schemas; each schema added removes its line here.
 */
const UNDESCRIBED_BODIES = [
  'GET /api/setup/runtime-detect 200',
  'PATCH /api/agents/:id request',
  'PATCH /api/connectors/:id request',
  'PATCH /api/memberships/:id request',
  'PATCH /api/model-connections/:id request',
  'PATCH /api/projects/:id request',
  'PATCH /api/runtime-profiles/:id request',
  'PATCH /api/sessions/:engineSessionId request',
  'PATCH /api/skills/:name request',
  'PATCH /api/workspaces/:id request',
  'POST /api/agents request',
  'POST /api/api-keys request',
  'POST /api/connectors request',
  'POST /api/invitations request',
  'POST /api/invitations/:id/accept request',
  'POST /api/memberships request',
  'POST /api/model-connections request',
  'POST /api/model-connections/:id/credential request',
  'POST /api/projects request',
  'POST /api/projects/:id/sessions request',
  'POST /api/runs/:id request',
  'POST /api/runs/:id/revoke-tokens request',
  'POST /api/runtime-connections request',
  'POST /api/runtime-profiles request',
  'POST /api/runtimes/:id 200',
  'POST /api/runtimes/:id request',
  'POST /api/secrets request',
  'POST /api/shares request',
  'POST /api/skills request',
  'POST /api/users request',
  'POST /api/workspaces request',
  'PUT /api/secrets/:id request',
];

describe('undescribed bodies', () => {
  it('only shrink: no route adds a body without a contract schema', () => {
    const undescribed = (body: ApiBody | undefined): boolean => body?.kind === 'json-undescribed';
    const live: string[] = [];
    for (const route of API_ROUTES) {
      const base = key(route.method, route.path);
      if ([route.request, ...(route.deprecatedRequests ?? [])].some(undescribed)) {
        live.push(`${base} request`);
      }
      for (const success of route.success) {
        if (undescribed(success.body)) live.push(`${base} ${String(success.status)}`);
      }
    }
    const frozen = new Set(UNDESCRIBED_BODIES);
    expect(
      live.filter((body) => !frozen.has(body)),
      'bodies with no contract schema; describe them in packages/contracts',
    ).toEqual([]);
    expect(
      UNDESCRIBED_BODIES.filter((body) => !live.includes(body)),
      'now described: delete these lines from UNDESCRIBED_BODIES',
    ).toEqual([]);
  });
});

describe('POST /api/skills (#1925 item 11)', () => {
  const requestContent = (): Record<string, Record<string, unknown>> => {
    const paths = document['paths'] as Record<string, Record<string, Record<string, unknown>>>;
    const body = paths['/api/skills']?.['post']?.['requestBody'] as Record<string, unknown>;
    return body['content'] as Record<string, Record<string, unknown>>;
  };

  it('describes the multipart/form-data import: a text `name`, then one `file` part per file', () => {
    expect(requestContent()['multipart/form-data']).toMatchObject({
      schema: {
        type: 'object',
        required: ['name', 'file'],
        properties: {
          name: { type: 'string' },
          file: {
            type: 'array',
            minItems: 1,
            items: { type: 'string', contentMediaType: 'application/octet-stream' },
          },
        },
      },
      encoding: { name: { contentType: 'text/plain' } },
    });
  });

  it('keeps the JSON + base64 body, marked deprecated', () => {
    expect(requestContent()['application/json']?.['schema']).toMatchObject({ deprecated: true });
  });
});

describe('a client generated by an off-the-shelf generator', () => {
  const me: MeResponse = {
    principalId: 'principal-1',
    kind: 'membership',
    role: 'owner',
    workspaceId: 'workspace-1',
    userId: 'user-1',
    label: 'Ada',
    features: ['chat'],
  };
  let server: Server;
  let baseUrl: string;
  const seen: {
    method: string | undefined;
    url: string | undefined;
    authorization: string | undefined;
  }[] = [];

  beforeAll(async () => {
    server = createServer((request, response) => {
      seen.push({
        method: request.method,
        url: request.url,
        authorization: request.headers.authorization,
      });
      if (request.method === 'GET' && request.url === '/api/me') {
        response.writeHead(200, { 'content-type': 'application/json' });
        response.end(JSON.stringify(me));
        return;
      }
      response.writeHead(404, { 'content-type': 'application/json' });
      response.end(JSON.stringify({ error: { code: 'not_found', message: 'Not found.' } }));
    });
    await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
    baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  });

  afterAll(async () => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  /** openapi-typescript's output for the document, type-checked together with `usage`. */
  async function typeCheckAgainstGeneratedTypes(usage: string): Promise<readonly string[]> {
    const generated = astToString(await openapiTS(structuredClone(document) as never));
    const dir = path.join(repoRoot, 'tests', 'docs', '.generated-client');
    const files = new Map([
      [path.join(dir, 'api.ts'), generated],
      [path.join(dir, 'usage.ts'), usage],
    ]);
    const options: ts.CompilerOptions = {
      strict: true,
      noEmit: true,
      target: ts.ScriptTarget.ES2023,
      module: ts.ModuleKind.NodeNext,
      moduleResolution: ts.ModuleResolutionKind.NodeNext,
      lib: ['lib.es2023.d.ts', 'lib.dom.d.ts'],
      types: [],
      skipLibCheck: true,
    };
    const host = ts.createCompilerHost(options);
    const readFileOnDisk = host.readFile.bind(host);
    const fileExistsOnDisk = host.fileExists.bind(host);
    const getSourceFileOnDisk = host.getSourceFile.bind(host);
    const normalise = (fileName: string): string => path.resolve(fileName);
    host.fileExists = (fileName) => files.has(normalise(fileName)) || fileExistsOnDisk(fileName);
    // The generated files exist only in memory, so their directory does too.
    host.directoryExists = (directory) =>
      normalise(directory) === dir || ts.sys.directoryExists(directory);
    host.readFile = (fileName) => files.get(normalise(fileName)) ?? readFileOnDisk(fileName);
    host.getSourceFile = (fileName, language, onError, shouldCreate) => {
      const text = files.get(normalise(fileName));
      return text === undefined
        ? getSourceFileOnDisk(fileName, language, onError, shouldCreate)
        : ts.createSourceFile(fileName, text, language);
    };
    const program = ts.createProgram([path.join(dir, 'usage.ts')], options, host);
    return ts
      .getPreEmitDiagnostics(program)
      .map((diagnostic) => ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n'));
  }

  it('generates types in which GET /api/me answers the MeResponse shape', async () => {
    const usage = [
      "import createClient from 'openapi-fetch';",
      "import type { paths } from './api.js';",
      "const client = createClient<paths>({ baseUrl: 'http://localhost:3000' });",
      'export async function workspaceOf(): Promise<string | undefined> {',
      "  const { data } = await client.GET('/api/me');",
      '  return data?.workspaceId;',
      '}',
    ].join('\n');
    expect(await typeCheckAgainstGeneratedTypes(usage)).toEqual([]);

    const wrong = usage.replace("'/api/me'", "'/api/not-a-route'");
    expect((await typeCheckAgainstGeneratedTypes(wrong)).length).toBeGreaterThan(0);
    // Two TypeScript programs: ~3 s on a 2-vCPU CI runner, too close to the 5 s default.
  }, 30_000);

  it('calls GET /api/me successfully', async () => {
    const client = createClient<{
      '/api/me': {
        get: { responses: { 200: { content: { 'application/json': MeResponse } } } };
      };
    }>({ baseUrl, headers: { authorization: 'Bearer ak_live_test' } });
    const { data, error, response } = await client.GET('/api/me');
    expect(error).toBeUndefined();
    expect(response.status).toBe(200);
    expect(MeResponseSchema.parse(data)).toEqual(me);

    // Tie the call to the emitted document: its 200 names the MeResponse component, which is the
    // contract schema converted, and the answer carries exactly what that component declares.
    const paths = document['paths'] as Record<string, Record<string, Record<string, unknown>>>;
    const responses = paths['/api/me']?.['get']?.['responses'] as Record<
      string,
      { content?: Record<string, { schema?: { $ref?: string } }> }
    >;
    const pointer = responses['200']?.content?.['application/json']?.schema?.$ref;
    expect(pointer).toBe('#/components/schemas/MeResponse');
    const schemas = (document['components'] as Record<string, Record<string, unknown>>)['schemas'];
    const component = schemas?.['MeResponse'] as {
      required?: string[];
      properties?: Record<string, unknown>;
    };
    const converted: Record<string, unknown> = {
      ...MeResponseSchema.toJSONSchema({
        target: 'draft-2020-12',
        io: 'output',
        unrepresentable: 'any',
      }),
    };
    delete converted['$schema'];
    expect(component).toEqual(converted);
    for (const field of component.required ?? []) expect(data).toHaveProperty(field);
    const declared = Object.keys(component.properties ?? {});
    expect(Object.keys(data ?? {}).filter((field) => !declared.includes(field))).toEqual([]);
    expect(seen.at(-1)).toEqual({
      method: 'GET',
      url: '/api/me',
      authorization: 'Bearer ak_live_test',
    });
  });
});
